// Get API response
const response = pm.response.json();

// TC-01: Status Code Validation
pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

// TC-02: Response Time Validation
pm.test("Response time is less than 3000ms", function () {
    pm.expect(pm.response.responseTime).to.be.below(3000);
});

// TC-03: Content-Type Validation
pm.test("Response format is JSON", function () {
    pm.expect(pm.response.headers.get("Content-Type"))
        .to.include("application/json");
});

// TC-04: Response should be an object
pm.test("Response body is an object", function () {
    pm.expect(response).to.be.an("object");
    pm.expect(response).to.not.be.an("array");
});

// TC-05: Product ID Validation
pm.test("Product ID should be 1", function () {
    pm.expect(response.id).to.eql(1);
});

// TC-06: Product Title Validation
pm.test("Product title is a non-empty string", function () {
    pm.expect(response.title).to.be.a("string");
    pm.expect(response.title.length).to.be.above(0);
});

// TC-07: Product Price Validation
pm.test("Product price is a number greater than 0", function () {
    pm.expect(response.price).to.be.a("number");
    pm.expect(response.price).to.be.above(0);
});

// TC-08: Product Rating Validation
pm.test("Product rating is between 0 and 5", function () {
    pm.expect(response.rating).to.be.a("number");
    pm.expect(response.rating).to.be.within(0, 5);
});

// TC-09: Category Validation
pm.test("Product category is not empty", function () {
    pm.expect(response.category).to.be.a("string");
    pm.expect(response.category.length).to.be.above(0);
});

// TC-10: Images Validation
pm.test("Product images should be an array", function () {
    pm.expect(response.images).to.be.an("array");
    pm.expect(response.images.length).to.be.above(0);
});

// TC-11: Thumbnail Validation
pm.test("Product thumbnail should be a non-empty string", function () {
    pm.expect(response.thumbnail).to.be.a("string");
    pm.expect(response.thumbnail.length).to.be.above(0);
});

// TC-12: Description Validation
pm.test("Product description should not be empty", function () {
    pm.expect(response.description).to.be.a("string");
    pm.expect(response.description.length).to.be.above(0);
});

const response = pm.response.json();

pm.test("Search results should not be empty", function () {
    pm.expect(response.products).to.be.an("array").that.is.not.empty;
});

pm.test("Search total should be a number", function () {
    pm.expect(response.total).to.be.a("number");
});

pm.test("Every result should have valid product details", function () {
    response.products.forEach(function(product) {
        pm.expect(product.id).to.be.a("number");
